// Pure functions (also unit-testable outside n8n)
function simpleHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0');
}
function normalizePhone(raw) {
  if (!raw) return '';
  let p = String(raw).replace(/[\s\-()]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (!p.startsWith('+')) p = '+' + p.replace(/^0+/, '');
  return p;
}
function validateLead(payload) {
  const errors = [];
  const name = String(payload.name || '').trim();
  const email = String(payload.email || '').trim().toLowerCase();
  const phoneRaw = payload.phone || payload.whatsapp || '';
  const phone = normalizePhone(phoneRaw);
  if (!name) errors.push('name is required');
  if (!email) errors.push('email is required');
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email is invalid');
  if (!phoneRaw) errors.push('phone is required');
  else if (!/^\+\d{7,15}$/.test(phone)) errors.push('phone is invalid');
  const idempotencyKey = payload.submission_id || ('lead_' + simpleHash(phone + '|' + email));
  return {
    valid: errors.length === 0,
    errors,
    lead: { name, email, phone, source: payload.source || 'website_form', idempotencyKey },
  };
}

// n8n wrapper
const item = $input.first().json;
const payload = item.body || item;
const r = validateLead(payload);
return [{ json: { valid: r.valid, errors: r.errors, ...r.lead, rawPayload: payload } }];

// Reads the (0 or 1) rows returned by the dedupe SELECT and decides
// whether this submission was already fully processed before.
const rows = $input.all().filter((i) => i.json && i.json.id);
const v = $('Validate and Normalize').first().json;
const existing = rows.length ? rows[0].json : null;
const duplicate = !!existing && !!existing.status && existing.status !== 'NEW';
return [{
  json: {
    ...v,
    existingId: existing ? existing.id : null,
    existingStatus: existing ? existing.status : null,
    duplicate,
  },
}];

