const resp = $input.first().json || {};
const ctx = $('Merge Lead Context').first().json;
const waMessageId = (resp.messages && resp.messages[0] && resp.messages[0].id) || null;
return [{ json: { ...ctx, waMessageId } }];

// Runs on the error output of the WhatsApp send. Builds one failure record
// that every downstream error-handling node reads from.
const ctx = $('Merge Lead Context').first().json;
const errItem = $input.first().json || {};
const message = (errItem.error && (errItem.error.message || JSON.stringify(errItem.error)))
  || errItem.message || 'WhatsApp send failed';
return [{
  json: {
    ...ctx,
    step: 'whatsapp_welcome',
    error: String(message).slice(0, 500),
  },
}];
